{
  "references": [
    {
      "id": "R1",
      "summary_ko": "착지 동작이 비현실적으로 보임."
    },
    {
      "id": "R2",
      "summary_ko": "몸이 부자연스러운 자세로 뒤집힘."
    },
    {
      "id": "R3",
      "summary_ko": "평균대를 다리 사이에 둔 채로 착지함."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "밝기 및 구조 변화 후 복귀하는 깜빡임 또는 순간 변형 패턴."
    },
    {
      "id": "C2",
      "summary_ko": "착지 중 체조 선수의 다리가 평균대 매트를 부자연스럽게 가로지르며 파고듦."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "착지 이상과 단순 화면 구조/밝기 변형 측정 간의 연관성을 텍스트만으로 확정하기 어렵습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "착지가 비현실적이라는 막연한 설명과 다리가 매트를 관통한다는 구체적 결함 간의 동일 여부가 불명확합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "신체 뒤집힘 현상과 일반적인 구조 변형 측정 가설 간의 직접적인 일치 여부를 판단하기 어렵습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "몸이 비정상적으로 뒤집히는 현상과 착지 시 다리가 매트를 관통하는 현상은 서로 다른 결함입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "평균대 사이로 착지하는 현상과 일반 측정 가설 간의 연관성이 텍스트만으로는 불명확합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "same",
      "reason_ko": "체조 선수가 착지 시 다리 사이에 평균대/매트를 끼우며 비정상적으로 착지하는 동일한 결함을 설명하고 있습니다."
    }
  ]
}
